-- Add directions_url to external_accommodations
ALTER TABLE external_accommodations ADD COLUMN IF NOT EXISTS directions_url TEXT;

-- Seed all hotels (run once — safe to re-run, upserts on name)
ON CONFLICT (name) DO UPDATE SET
  description    = EXCLUDED.description,
  url            = EXCLUDED.url,
  directions_url = EXCLUDED.directions_url,
  sort_order     = EXCLUDED.sort_order,
  is_active      = EXCLUDED.is_active;
